INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(65260293, 'Element Magician', '元素魔术师', 'エレメント・マジシャン', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1200, '这只怪兽在场上有特定属性的怪兽存在的场合，得到以下的效果。 ●水属性：这张卡的控制权不能变更。 ●风属性：这张卡战斗破坏对方怪兽的场合，只有1次可以再度攻击。'),
(92755808, 'Element Saurus', '元素恐龙', 'エレメント・ザウルス', 'Effect Monster', 'Dinosaur', 'DARK', 4, 1500, 1200, '这只怪兽在场上有特定属性的怪兽存在的场合，得到以下的效果。 ●炎属性：这张卡攻击力上升500。 ●地属性：这张卡战斗破坏的怪兽的效果无效化。'),
(66712593, 'Element Soldier', '元素战士', 'エレメント・ソルジャー', 'Effect Monster', 'Fiend', 'DARK', 4, 1500, 1200, '这只怪兽在场上有特定属性的怪兽存在的场合，得到以下的效果。 ●水属性：这张卡的控制权不能变更。 ●地属性：这张卡战斗破坏的怪兽的效果无效化。'),
(97623219, 'Element Valkyrie', '元素女武神', 'エレメント・ヴァルキリー', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1500, 1200, '这只怪兽在场上有特定的属性的怪兽存在的场合，得到以下的效果。 ●炎属性：这张卡攻击力上升500。 ●水属性：这张卡的控制权不能变更。'),
(94253609, 'Elemental Absorber', '元素吸收器', 'エレメンタル・アブソーバー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把手卡1张怪兽卡从游戏中除外。持有和这个效果除外的怪兽卡相同的属性的对方怪兽，只要这张卡在场上存在不能攻击宣言。'),
(61411502, 'Elemental Burst', '元素爆发', 'エレメンタルバースト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的风·水·炎·地属性的怪兽各1只作为祭品才能发动。对方场上存在的卡全部破坏。'),
(32965616, 'Elemental Grace Doriado', '精灵圣后 多里雅德', '精霊神后 ドリアード', 'Effect Monster', 'Spellcaster', 'LIGHT', 9, NULL, NULL, '这张卡不能通常召唤。自己·对方的墓地的怪兽属性是6种类以上的场合才能特殊召唤。 ①：这张卡的攻击力·守备力上升自己·对方的墓地的怪兽的属性种类×500。 ②：对方把怪兽特殊召唤之际，把自己墓地3只怪兽除外才能发动。那次特殊召唤无效，那些怪兽破坏。'),
(40854197, 'Elemental HERO Absolute Zero', '元素－英雄 绝对零度', 'E・HERO アブソルートZero', 'Fusion Monster', 'Warrior', 'WATER', 8, 2500, 2000, '名字带有「英雄」的怪兽＋水属性怪兽 这张卡不能作融合召唤以外的特殊召唤。这张卡的攻击力上升场上表侧表示存在的「元素英雄 绝对零度侠」以外的水属性怪兽数量×500的数值。这张卡从场上离开时，对方场上存在的怪兽全部破坏。'),
(11502550, 'Elemental HERO Air Neos', '元素英雄 天空新宇侠', 'E・HERO エアー・ネオス', 'Fusion Monster', 'Warrior', 'WIND', 7, 2500, 2000, '「元素英雄 新宇侠」＋「新空间侠·天空蜂鸟」 把自己场上存在的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。自己基本分比对方基本分少的场合，这张卡的攻击力上升那个数值。结束阶段时这张卡回到额外卡组。'),
(55171412, 'Elemental HERO Aqua Neos', '元素－英雄 水波新宇侠', 'E・HERO アクア・ネオス', 'Fusion Monster', 'Warrior', 'WATER', 7, 2500, 2000, '「元素英雄 新宇侠」＋「新空间侠·水波海豚」 把自己场上存在的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。丢弃1张手卡，随机选择对方的1张手卡破坏。这个效果1回合只能使用1次。结束阶段时这张卡回到额外卡组。'),
(21844576, 'Elemental HERO Avian', '元素－英雄 羽毛人', 'E・HERO フェザーマン', 'Normal Monster', 'Warrior', 'WIND', 3, 1000, 1000, '拥有操纵风在天空飞舞之翼的元素英雄。以来自天空的一击羽翼击破来审判邪恶。'),
(59793705, 'Elemental HERO Bladedge', '元素－英雄 刀锋人', 'E・HERO エッジマン', 'Effect Monster', 'Warrior', 'EARTH', 7, 2600, 1800, '①：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(63060238, 'Elemental HERO Blazeman', '元素－英雄 烈焰人', 'E・HERO ブレイズマン', 'Effect Monster', 'Warrior', 'FIRE', 4, 1200, 1800, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「融合」加入手卡。 ②：自己主要阶段才能发动。从卡组把「元素英雄 烈焰侠」以外的1只「元素英雄」怪兽送去墓地。这张卡直到回合结束时变成和这个效果送去墓地的怪兽相同属性·攻击力·守备力。这个效果的发动后，直到回合结束时自己不是融合怪兽不能特殊召唤。'),
(64655485, 'Elemental HERO Brave Neos', '元素－英雄 勇猛新宇侠', 'E・HERO ブレイヴ・ネオス', 'Fusion Monster', 'Warrior', 'LIGHT', 7, 2500, 2000, '「元素英雄 新宇侠」＋4星以下的效果怪兽 这张卡不用融合召唤不能特殊召唤。 ①：这张卡的攻击力上升自己墓地的「新空间侠」怪兽以及「英雄」怪兽数量×100。 ②：这张卡战斗破坏对方怪兽时才能发动。把有「元素英雄 新宇侠」的卡名记述的1张魔法·陷阱卡从卡组加入手卡。'),
(79979666, 'Elemental HERO Bubbleman', '元素－英雄 泡沫人', 'E・HERO バブルマン', 'Effect Monster', 'Warrior', 'WATER', 4, 800, 1200, '①：手卡只有这1张卡的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·反转召唤·特殊召唤时才能发动（这个效果在自己的手卡·场上没有其他卡存在的场合才能发动和处理）。自己抽2张。'),
(58932615, 'Elemental HERO Burstinatrix', '元素－英雄 爆炎女郎', 'E・HERO バーストレディ', 'Normal Monster', 'Warrior', 'FIRE', 3, 1200, 800, '操纵火焰的元素英雄一点红。红莲之炎爆热火焰将烧尽邪恶。'),
(80908502, 'Elemental HERO Captain Gold', '元素－英雄 黄金队长', 'E・HERO キャプテン・ゴールド', 'Effect Monster', 'Warrior', 'LIGHT', 4, 2100, 800, '把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「摩天楼」加入手卡。此外，场上没有「摩天楼」存在的场合，这张卡破坏。'),
(17032740, 'Elemental HERO Chaos Neos', '元素英雄 混沌新宇侠', 'E・HERO カオス・ネオス', 'Fusion Monster', 'Warrior', 'DARK', 9, 3000, 2500, '「元素英雄 新宇侠」＋「新空间侠·黑暗豹」＋「新空间侠·光辉青苔」 把自己场上存在的上记的卡回到卡组的场合才能从融合卡组特殊召唤（不需要「融合」魔法卡）。结束阶段时这张卡回到融合卡组，场上存在的全部表侧表示怪兽变成盖放的状态。进行3次投掷硬币，进行表出现次数的以下处理。这个效果1回合只有1次在自己的主要阶段1才能使用。 ●3次：对方场上存在的全部怪兽破坏。 ●2次：这个回合对方场上表侧表示存在的效果怪兽全部效果无效化。 ●1次：自己场上存在的全部怪兽回到持有者手卡。'),
(84327329, 'Elemental HERO Clayman', '元素－英雄 黏土人', 'E・HERO クレイマン', 'Normal Monster', 'Warrior', 'EARTH', 4, 800, 2000, '拥有黏土制结实身体的元素英雄。挺身守住其他元素英雄同伴。'),
(95486586, 'Elemental HERO Core', '元素英雄 地核侠', 'E・HERO Core', 'Fusion Monster', 'Warrior', 'EARTH', 9, 2700, 2200, '「元素英雄」怪兽×3 这张卡不用融合召唤不能特殊召唤。 ①：1回合1次，这张卡成为攻击对象时才能发动。这张卡的攻击力直到那次伤害步骤结束时变成2倍。 ②：这张卡进行战斗的战斗阶段结束时，以场上1只怪兽为对象才能发动。那只怪兽破坏。 ③：这张卡被战斗·效果破坏时，以自己墓地1只8星以下的「元素英雄」融合怪兽为对象才能发动。那只怪兽无视召唤条件特殊召唤。'),
(90050480, 'Elemental HERO Cosmo Neos', '元素－英雄 宇宙新宇侠', 'E・HERO コスモ・ネオス', 'Fusion Monster', 'Warrior', 'LIGHT', 11, 3500, 3000, '「元素英雄 新宇侠」＋属性不同的「新空间侠」怪兽×3 让自己场上的上记卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：这张卡从额外卡组的特殊召唤成功的场合才能发动。这个回合对方不能把场上发动的效果发动。对方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。 ②：结束阶段发动。这张卡回到额外卡组，对方场上的卡全部破坏。'),
(28677304, 'Elemental HERO Dark Neos', '元素－英雄 漆黑新宇侠', 'E・HERO ブラック・ネオス', 'Fusion Monster', 'Warrior', 'DARK', 7, 2500, 2000, '「元素英雄 新宇侠」＋「新空间侠·黑暗豹」 把自己场上存在的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。可以选择场上表侧表示存在的1只效果怪兽。只要这张卡在自己场上表侧表示存在，选择的怪兽直到从场上离开效果无效化（这个效果可以选择的怪兽最多1只）。结束阶段时这张卡回到额外卡组。'),
(41517968, 'Elemental HERO Darkbright', '元素－英雄 暗辉人', 'E・HERO ダーク・ブライトマン', 'Fusion Monster', 'Warrior', 'DARK', 6, 2000, 1000, '「元素英雄 电光侠」＋「元素英雄 死灵暗侠」 这只怪兽不能作融合召唤以外的特殊召唤。这张卡攻击守备表示怪兽时，若这张卡的攻击力超过守备表示怪兽的守备力，给与对方基本分那个数值的战斗伤害。这张卡攻击的场合，伤害步骤结束时变成守备表示。这张卡被破坏时，把对方场上1只怪兽破坏。'),
(31111109, 'Elemental HERO Divine Neos', '元素英雄 神·新宇侠', 'E・HERO ゴッド・ネオス', 'Fusion Monster', 'Warrior', 'LIGHT', 12, 2500, 2500, '这张卡不用融合召唤不能特殊召唤。名字带有「新宇」·「新空间侠」·「英雄」的怪兽各有1只以上，合计5只的怪兽为融合素材作融合召唤。1回合1次，可以通过把自己墓地存在的1只名字带有「新宇」·「新空间侠」·「英雄」的怪兽从游戏中除外，这张卡的攻击力上升500。并且，直到结束阶段时得到和那只怪兽相同的效果。'),
(29343734, 'Elemental HERO Electrum', '元素－英雄 万灵贤侠', 'E・HERO エリクシーラー', 'Fusion Monster', 'Warrior', 'LIGHT', 10, 2900, 2600, '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」＋「元素英雄 黏土侠」＋「元素英雄 水泡侠」 这只怪兽不能作融合召唤以外的特殊召唤。这张卡的属性也同时当作「风」「水」「炎」「地」使用。这张卡融合召唤成功时，从游戏中除外的全部卡回到持有者的卡组，并洗切卡组。对方场上每存在1只和这张卡相同属性的怪兽，这张卡攻击力上升300。'),
(33574806, 'Elemental HERO Escuridao', '元素－英雄 幽冥', 'E・HERO エスクリダオ', 'Fusion Monster', 'Warrior', 'DARK', 8, 2500, 2000, '名字带有「元素英雄」的怪兽＋暗属性怪兽 这张卡不用融合召唤不能特殊召唤。这张卡的攻击力上升自己墓地存在的名字带有「元素英雄」的怪兽数量×100的数值。'),
(35809262, 'Elemental HERO Flame Wingman', '元素－英雄 火焰翼人', 'E・HERO フレイム・ウィングマン', 'Fusion Monster', 'Warrior', 'WIND', 6, 2100, 1200, '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」 这张卡不用融合召唤不能特殊召唤。 ①：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(93347961, 'Elemental HERO Flame Wingman - Infernal Rage', '元素－英雄 火焰翼人－火焰射击', 'E・HERO フレイム・ウィングマン－フレイム・シュート', 'Fusion Monster', 'Warrior', 'WIND', 8, 2100, 1200, '属性不同的「元素英雄」怪兽×2 这张卡不用融合召唤不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从自己的卡组·墓地选1张「至爱」卡加入手卡。 ②：把用通常怪兽为素材作融合召唤的这张卡解放才能发动。从卡组·额外卡组把1只7星以下的不能通常召唤的「元素英雄」怪兽无视召唤条件特殊召唤。'),
(81566151, 'Elemental HERO Flare Neos', '元素英雄 火焰新宇侠', 'E・HERO フレア・ネオス', 'Fusion Monster', 'Warrior', 'FIRE', 7, 2500, 2000, '「元素英雄 新宇侠」＋「新空间侠·火焰甲虫」 把自己场上存在的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。这张卡的攻击力上升场上的魔法·陷阱卡数量×400的数值。结束阶段时这张卡回到额外卡组。'),
(69572169, 'Elemental HERO Flash', '元素英雄 电闪侠', 'E・HERO フラッシュ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1100, 1600, '这张卡被战斗破坏送去墓地时，可以从自己墓地把这张卡和名字带有「元素英雄」的怪兽卡3种类从游戏中除外，选择自己墓地存在的1张通常魔法卡加入手卡。'),
(16304628, 'Elemental HERO Gaia', '元素－英雄 盖亚', 'E・HERO ガイア', 'Fusion Monster', 'Warrior', 'EARTH', 6, 2200, 2600, '「元素英雄」怪兽＋地属性怪兽 这张卡不用融合召唤不能特殊召唤。 ①：这张卡融合召唤成功的场合，以对方场上1只表侧表示怪兽为对象发动。直到回合结束时，那只怪兽的攻击力变成一半，这张卡的攻击力上升那个数值。'),
(85507811, 'Elemental HERO Glow Neos', '元素英雄 光辉新宇侠', 'E・HERO グロー・ネオス', 'Fusion Monster', 'Warrior', 'LIGHT', 7, 2500, 2000, '「元素英雄 新宇侠」＋「新空间侠·光辉青苔」 把自己场上存在的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。结束阶段时这张卡回到额外卡组。把对方场上表侧表示存在的1张卡破坏，这张卡得到那张卡的种类的以下效果：这个效果1回合只有1次在自己的主要阶段一才能使用。 ●怪兽卡-这个回合，这张卡不能进行战斗。 ●魔法卡-这张卡可以直接攻击对方玩家。 ●陷阱卡-这张卡变成守备表示。'),
(48996569, 'Elemental HERO Grand Neos', '元素－英雄 大地新宇侠', 'E・HERO グラン・ネオス', 'Fusion Monster', 'Warrior', 'EARTH', 7, 2500, 2000, '「元素英雄 新宇侠」＋「新空间侠·大地鼹鼠」 让自己场上的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」魔法卡）。1回合1次，可以选择对方场上1只怪兽回到持有者手卡。此外，结束阶段时，这张卡回到额外卡组。'),
(36841733, 'Elemental HERO Grandmerge', '元素－英雄 统合人', 'E・HERO グランドマン', 'Fusion Monster', 'Warrior', 'LIGHT', 6, NULL, NULL, '「英雄」通常怪兽×2 这张卡不用融合召唤不能特殊召唤。 ①：这张卡的攻击力·守备力上升作为这张卡的融合素材的怪兽的原本等级合计×300。 ②：这张卡战斗破坏对方怪兽时，把这张卡解放才能发动。从额外卡组把1只「元素英雄」融合怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽不能向持有自身的等级以下的等级的怪兽攻击。'),
(3642509, 'Elemental HERO Great Tornado', '元素－英雄 大龙卷', 'E・HERO Great TORNADO', 'Fusion Monster', 'Warrior', 'WIND', 8, 2800, 2200, '「元素英雄」怪兽＋风属性怪兽 这张卡不用融合召唤不能特殊召唤。 ①：这张卡融合召唤成功的场合发动。对方场上的全部怪兽的攻击力·守备力变成一半。'),
(98266377, 'Elemental HERO Heat', '元素英雄 炽热侠', 'E・HERO ザ・ヒート', 'Effect Monster', 'Pyro', 'FIRE', 4, 1600, 1200, '①：这张卡的攻击力上升自己场上的「元素英雄」怪兽数量×200。'),
(14124483, 'Elemental HERO Honest Neos', '元素－英雄 真诚新宇侠', 'E・HERO オネスティ・ネオス', 'Effect Monster', 'Warrior', 'LIGHT', 7, 2500, 2000, '这个卡名的①②的效果1回合各能使用1次，对方回合也能发动。 ①：把这张卡从手卡丢弃，以场上1只「英雄」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升2500。 ②：从手卡丢弃1只「英雄」怪兽才能发动。这张卡的攻击力直到回合结束时上升丢弃的怪兽的攻击力数值。'),
(41077745, 'Elemental HERO Ice Edge', '元素英雄 冰棱侠', 'E・HERO アイスエッジ', 'Effect Monster', 'Warrior', 'WATER', 3, 800, 900, '1回合1次，自己的主要阶段一丢弃1张手卡发动。这个回合这张卡可以直接攻击对方玩家。此外，这张卡直接攻击给与对方基本分战斗伤害时，可以把对方的魔法与陷阱卡区域盖放的1张卡破坏。'),
(68745629, 'Elemental HERO Inferno', '元素英雄 爆裂火焰侠', 'E・HERO フレイム・ブラスト', 'Fusion Monster', 'Pyro', 'FIRE', 8, 2300, 1600, '「元素英雄 炽热侠」＋「元素英雄 火焰女郎」 这只怪兽不能作融合召唤以外的特殊召唤。和水属性怪兽战斗的场合，伤害步骤内这只怪兽的攻击力上升1000。'),
(62107981, 'Elemental HERO Knospe', '元素英雄 小花蕾', 'E・HERO クノスペ', 'Effect Monster', 'Plant', 'EARTH', 3, 600, 1000, '每次给与对方玩家战斗伤害，这张卡的攻击力上升100，守备力下降100。只要除这张卡以外的名字带有「元素英雄」的怪兽在自己场上表侧表示存在，对方不能把这张卡选择作为攻击对象，这张卡可以直接攻击对方玩家。'),
(95362816, 'Elemental HERO Lady Heat', '元素英雄 火焰女郎', 'E・HERO レディ・オブ・ファイア', 'Effect Monster', 'Pyro', 'FIRE', 4, 1300, 1000, '自己回合的结束阶段时，给与对方基本分自己场上表侧表示存在的名字带有「元素英雄」的怪兽数量×200的数值的伤害。'),
(59392529, 'Elemental HERO Liquid Soldier', '元素－英雄 液态人', 'E・HERO リキッドマン', 'Effect Monster', 'Warrior', 'WATER', 4, 1400, 1300, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤时，以除「元素英雄 液态侠」外的自己墓地1只4星以下的「英雄」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡成为「英雄」融合怪兽的融合召唤的素材，被送去墓地的场合或者被除外的场合才能发动。自己抽2张。那之后，选自己1张手卡丢弃。'),
(78512663, 'Elemental HERO Magma Neos', '元素英雄 熔岩新宇侠', 'E・HERO マグマ・ネオス', 'Fusion Monster', 'Warrior', 'FIRE', 9, 3000, 2500, '「元素英雄 新宇侠」＋「新空间侠·火焰甲虫」＋「新空间侠·大地鼹鼠」 把自己场上存在的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。这张卡的攻击力上升场上的卡的数量×400的数值。结束阶段时这张卡回到额外卡组。这个效果回到额外卡组时，场上存在的全部卡回到持有者手卡。'),
(5128859, 'Elemental HERO Marine Neos', '元素英雄 海洋新宇侠', 'E・HERO マリン・ネオス', 'Fusion Monster', 'Warrior', 'WATER', 8, 2800, 2300, '「元素英雄 新宇侠」＋「新空间侠·海洋海豚」 让自己场上的上记卡回到卡组的场合才能从额外卡组特殊召唤。 ①：1回合1次，自己主要阶段才能发动。对方手卡随机选1张破坏。'),
(14225239, 'Elemental HERO Mariner', '元素英雄 水手侠', 'E・HERO セイラーマン', 'Fusion Monster', 'Warrior', 'WATER', 5, 1400, 1000, '「元素英雄 水泡侠」＋「元素英雄 羽翼侠」 这只怪兽不用融合召唤不能特殊召唤。自己的魔法与陷阱卡区域有卡盖放的场合，这张卡可以直接攻击对方玩家。'),
(52031567, 'Elemental HERO Mudballman', '元素英雄 泥球侠', 'E・HERO マッドボールマン', 'Fusion Monster', 'Warrior', 'EARTH', 6, 1900, 3000, '「元素英雄 水泡侠」＋「元素英雄 黏土侠」 这只怪兽不能作融合召唤以外的特殊召唤。'),
(40080312, 'Elemental HERO Nebula Neos', '元素－英雄 星云新宇侠', 'E・HERO ネビュラ・ネオス', 'Fusion Monster', 'Warrior', 'EARTH', 9, 3000, 2500, '「元素英雄 新宇侠」＋「新空间侠·大地鼹鼠」＋「新空间侠·黑暗豹」 让自己场上的上记卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：这张卡从额外卡组的特殊召唤成功的场合发动。自己从卡组抽出对方场上的卡的数量。那之后，选场上1张表侧表示的卡，那个效果直到回合结束时无效。 ②：结束阶段发动。这张卡回到额外卡组，场上的卡全部里侧表示除外。'),
(81003500, 'Elemental HERO Necroid Shaman', '元素英雄 死灵萨满', 'E・HERO ネクロイド・シャーマン', 'Fusion Monster', 'Warrior', 'DARK', 6, 1900, 1800, '「元素英雄 荒野侠」＋「元素英雄 死灵暗侠」 这张卡不用融合召唤不能特殊召唤。 ①：这张卡特殊召唤成功的场合，以对方场上1只怪兽为对象发动。那只对方怪兽破坏。那之后，从对方墓地选1只怪兽在对方场上特殊召唤。'),
(89252153, 'Elemental HERO Necroshade', '元素－英雄 死灵暗黑人', 'E・HERO ネクロダークマン', 'Effect Monster', 'Warrior', 'DARK', 5, 1600, 1800, '①：只在这张卡在墓地存在才有1次，自己在5星以上的「元素英雄」怪兽召唤的场合需要的解放可以不用。'),
(5285665, 'Elemental HERO Neo Bubbleman', '元素英雄 新水泡侠', 'E・HERO バブルマン・ネオ', 'Effect Monster', 'Warrior', 'WATER', 4, 800, 1200, '这张卡不能通常召唤。把自己场上存在的「元素英雄 水泡侠」和手卡的「突然变异」送去墓地的场合才能特殊召唤。只要这张卡在场上表侧表示存在，卡名当作「元素英雄 水泡侠」使用。和这张卡进行战斗的怪兽在伤害步骤结束时破坏。'),
(89943723, 'Elemental HERO Neos', '元素－英雄 新宇侠', 'E・HERO ネオス', 'Normal Monster', 'Warrior', 'LIGHT', 7, 2500, 2000, '从新宇宙来的新元素英雄。凭借与新空间侠接触融合，发挥未知的力量！'),
(69884162, 'Elemental HERO Neos Alius', '元素－英雄 次新宇侠', 'E・HERO アナザー・ネオス', 'Gemini Monster', 'Warrior', 'LIGHT', 4, 1900, 1300, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡只要在怪兽区域存在，卡名当作「元素英雄 新宇侠」使用。'),
(90307498, 'Elemental HERO Neos Kluger', '元素－英雄 新宇智者', 'E・HERO ネオス・クルーガー', 'Fusion Monster', 'Spellcaster', 'LIGHT', 9, 3000, 2500, '「元素英雄 新宇侠」＋「于贝尔」 这张卡不用融合召唤不能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡和对方怪兽进行战斗的伤害计算前才能发动。给与对方那只对方怪兽的攻击力数值的伤害。 ②：表侧表示的这张卡因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。从手卡·卡组把1只「新宇贤者」无视召唤条件特殊召唤。'),
(72926163, 'Elemental HERO Neos Knight', '元素英雄 新宇骑士', 'E・HERO ネオス・ナイト', 'Fusion Monster', 'Warrior', 'LIGHT', 7, 2500, 1000, '「元素英雄 新宇侠」＋战士族怪兽 这张卡不用融合召唤不能特殊召唤。 ①：这张卡的攻击力上升作为这张卡的融合素材的「元素英雄 新宇侠」以外的怪兽的原本攻击力一半的数值。 ②：这张卡在同1次的战斗阶段中可以作2次攻击。 ③：这张卡的战斗发生的对对方的战斗伤害变成0。'),
(1945387, 'Elemental HERO Nova Master', '元素－英雄 新星主宰者', 'E・HERO ノヴァマスター', 'Fusion Monster', 'Warrior', 'FIRE', 8, 2600, 2100, '「元素英雄」怪兽＋炎属性怪兽 这张卡不用融合召唤不能特殊召唤。 ①：这张卡战斗破坏对方怪兽的场合发动。自己从卡组抽1张。'),
(37195861, 'Elemental HERO Ocean', '元素－英雄 海洋人', 'E・HERO オーシャン', 'Effect Monster', 'Warrior', 'WATER', 4, 1500, 1200, '①：1回合1次，自己准备阶段以自己的场上·墓地1只「英雄」怪兽为对象才能发动。那只自己的「英雄」怪兽回到持有者手卡。'),
(41436536, 'Elemental HERO Phoenix Enforcer', '元素－英雄 不死鸟魔侠', 'E・HERO フェニックスガイ', 'Fusion Monster', 'Warrior', 'FIRE', 6, 2100, 1200, '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」 这只怪兽不能作融合召唤以外的特殊召唤。这张卡不会被战斗破坏。'),
(60493189, 'Elemental HERO Plasma Vice', '元素英雄 电离钳侠', 'E・HERO プラズマヴァイスマン', 'Fusion Monster', 'Warrior', 'EARTH', 8, 2600, 2300, '「元素英雄 电光侠」＋「元素英雄 金刃侠」 这只怪兽不能作融合召唤以外的特殊召唤。这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。可以丢弃1张手卡把对方场上1只攻击表示怪兽破坏。'),
(51085303, 'Elemental HERO Poison Rose', '元素英雄 鲜花女郎', 'E・HERO ブルーメ', 'Effect Monster', 'Plant', 'EARTH', 6, 1900, 2000, '这张卡不能通常召唤。这张卡用「花瓣」的效果才能特殊召唤。对方只能把「元素英雄 鲜花女郎」选择作为攻击对象。每次给与对方玩家战斗伤害，这张卡的攻击力上升200，守备力下降200。'),
(89312388, 'Elemental HERO Prisma', '元素－英雄 棱镜侠', 'E・HERO プリズマー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1100, '①：1回合1次，把额外卡组1只融合怪兽给对方观看，把那只怪兽有卡名记述的1只融合素材怪兽从卡组送去墓地才能发动。直到结束阶段，这张卡当作和为这个效果发动而送去墓地的怪兽同名卡使用。'),
(47737087, 'Elemental HERO Rampart Blaster', '元素英雄 铁壁炮手', 'E・HERO ランパートガンナー', 'Fusion Monster', 'Warrior', 'EARTH', 6, 2000, 2500, '「元素英雄 爆热女郎」＋「元素英雄 黏土侠」 这只怪兽不能作融合召唤以外的特殊召唤。这张卡表侧守备表示的场合，可以用守备表示的状态直接攻击对方玩家。那个场合，这张卡的攻击力在伤害计算时变成一半。'),
(50720316, 'Elemental HERO Shadow Mist', '元素－英雄 影雾', 'E・HERO シャドー・ミスト', 'Effect Monster', 'Warrior', 'DARK', 4, 1000, 1500, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「变化」速攻魔法卡加入手卡。 ②：这张卡被送去墓地的场合才能发动。从卡组把「元素英雄 影雾女郎」以外的1只「英雄」怪兽加入手卡。'),
(25366484, 'Elemental HERO Shining Flare Wingman', '元素－英雄 闪耀光焰翼人', 'E・HERO シャイニング・フレア・ウィングマン', 'Fusion Monster', 'Warrior', 'LIGHT', 8, 2500, 2100, '「元素英雄 火焰翼侠」＋「元素英雄 电光侠」 这张卡不用融合召唤不能特殊召唤。 ①：这张卡的攻击力上升自己墓地的「元素英雄」卡数量×300。 ②：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(56733747, 'Elemental HERO Shining Neos Wingman', '元素－英雄 闪耀新宇翼人', 'E・HERO シャイニング・ネオス・ウィングマン', 'Fusion Monster', 'Warrior', 'LIGHT', 8, 3100, 2500, '「元素英雄 新宇侠」＋「翼侠」融合怪兽 这张卡不用融合召唤不能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合才能发动。把最多有场上的怪兽的属性种类数量的对方场上的卡破坏。 ②：场上的这张卡攻击力上升自己墓地的怪兽数量×300，不会被效果破坏。 ③：这张卡战斗破坏怪兽的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(88820235, 'Elemental HERO Shining Phoenix Enforcer', '元素英雄 闪光凤凰人', 'E・HERO シャイニング・フェニックスガイ', 'Fusion Monster', 'Warrior', 'FIRE', 8, 2500, 2100, '「元素英雄 凤凰人」＋「元素英雄 电光侠」 这只怪兽不能作融合召唤以外的特殊召唤。自己墓地每有1张名字带有「元素英雄」的卡，这张卡的攻击力上升300。这张卡不会被战斗破坏。'),
(45195443, 'Elemental HERO Solid Soldier', '元素－英雄 固态人', 'E・HERO ソリッドマン', 'Effect Monster', 'Warrior', 'EARTH', 4, 1300, 1100, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从手卡把1只4星以下的「英雄」怪兽特殊召唤。 ②：这张卡被魔法卡的效果从怪兽区域送去墓地的场合，以「元素英雄 固态侠」以外的自己墓地1只「英雄」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(20721928, 'Elemental HERO Sparkman', '元素－英雄 闪光人', 'E・HERO スパークマン', 'Normal Monster', 'Warrior', 'LIGHT', 4, 1600, 1400, '自如运用各种武器，属于光之战士的元素英雄。神圣光辉电光一闪将切断邪恶的退路。'),
(13256226, 'Elemental HERO Spirit of Neos', '元素－英雄 新宇侠之精灵', 'E・HERO スピリット・オブ・ネオス', 'Effect Monster', 'Warrior', 'LIGHT', 7, 2500, 2000, '这个卡名的①②③的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时才能发动。这张卡从手卡守备表示特殊召唤。这个效果特殊召唤的这张卡不会被战斗破坏。 ②：这张卡特殊召唤成功的场合才能发动。从卡组把1张有「元素英雄」怪兽的卡名记述的魔法·陷阱卡或者「融合」加入手卡。 ③：自己主要阶段才能发动。这张卡回到持有者卡组，从卡组把1只「元素英雄」通常怪兽特殊召唤。'),
(81197327, 'Elemental HERO Steam Healer', '元素英雄 蒸汽医治者', 'E・HERO スチーム・ヒーラー', 'Fusion Monster', 'Warrior', 'WATER', 5, 1800, 1000, '「元素英雄 爆热女郎」＋「元素英雄 水泡侠」 这张卡不用融合召唤不能特殊召唤。这张卡战斗破坏怪兽送去墓地时，自己基本分回复破坏的怪兽的原本攻击力的数值。'),
(49352945, 'Elemental HERO Storm Neos', '元素英雄 风暴新宇侠', 'E・HERO ストーム・ネオス', 'Fusion Monster', 'Warrior', 'WIND', 9, 3000, 2500, '「元素英雄 新宇侠」＋「新空间侠·水波海豚」＋「新空间侠·天空蜂鸟」 把自己场上存在的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。1回合只有1次在自己的主要阶段时可以把场上的魔法·陷阱卡全部破坏。结束阶段时这张卡回到额外卡组。这个效果回到额外卡组时，场上存在的全部卡回到卡组洗切。'),
(40044918, 'Elemental HERO Stratos', '元素－英雄 大气人', 'E・HERO エアーマン', 'Effect Monster', 'Warrior', 'WIND', 4, 1800, 300, '①：这张卡召唤·特殊召唤时，可以从以下效果选择1个发动。 ●把最多有自己场上的其他的「英雄」怪兽数量的场上的魔法·陷阱卡破坏。 ●从卡组把1只「英雄」怪兽加入手卡。'),
(22908820, 'Elemental HERO Sunrise', '元素－英雄 日升侠', 'E・HERO サンライザー', 'Fusion Monster', 'Warrior', 'LIGHT', 7, 2500, 1200, '属性不同的「英雄」怪兽×2 这张卡不用融合召唤不能特殊召唤。这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「奇迹融合」加入手卡。 ②：自己场上的怪兽的攻击力上升自己场上的怪兽的属性种类×200。 ③：其他的自己的「英雄」怪兽进行战斗的攻击宣言时，以场上1张卡为对象才能发动。那张卡破坏。'),
(83121692, 'Elemental HERO Tempest', '元素英雄 暴风侠', 'E・HERO テンペスター', 'Fusion Monster', 'Warrior', 'WIND', 8, 2800, 2800, '「元素英雄 羽翼侠」＋「元素英雄 电光侠」＋「元素英雄 水泡侠」 这张卡不用融合召唤不能特殊召唤。 ①：把自己场上1张其他卡送去墓地，以自己场上1只怪兽为对象才能发动。这张卡表侧表示存在期间，那只怪兽不会被战斗破坏。'),
(74711057, 'Elemental HERO Terra Firma', '元素－英雄 地球', 'E・HERO ジ・アース', 'Fusion Monster', 'Warrior', 'EARTH', 8, 2500, 2000, '「元素英雄 海洋侠」＋「元素英雄 森林侠」 这张卡不用融合召唤不能特殊召唤。 ①：把这张卡以外的自己场上1只表侧表示的「元素英雄」怪兽解放才能发动。这张卡的攻击力直到回合结束时上升解放的怪兽的攻击力数值。'),
(22061412, 'Elemental HERO The Shining', '元素－英雄 闪耀', 'E・HERO The シャイニング', 'Fusion Monster', 'Warrior', 'LIGHT', 8, 2600, 2100, '名字带有「元素英雄」的怪兽＋光属性怪兽 这张卡不用融合召唤不能特殊召唤。这张卡的攻击力上升从游戏中除外的自己的名字带有「元素英雄」的怪兽数量×300的数值。这张卡从场上送去墓地时，可以选择从游戏中除外的最多2只自己的名字带有「元素英雄」的怪兽加入手卡。'),
(61204971, 'Elemental HERO Thunder Giant', '元素英雄 雷霆巨人', 'E・HERO サンダー・ジャイアント', 'Fusion Monster', 'Warrior', 'LIGHT', 6, 2400, 1500, '「元素英雄 电光侠」＋「元素英雄 黏土侠」 这张卡不用融合召唤不能特殊召唤。 ①：1回合1次，丢弃1张手卡，以场上1只表侧表示怪兽为对象才能发动。原本攻击力比这张卡的攻击力低的那只怪兽破坏。'),
(19222426, 'Elemental HERO Thunder Giant - Voltic Thunder', '元素－英雄 雷霆巨人－雷霆漩涡', 'E・HERO サンダー・ジャイアント－ボルティック・サンダー', 'Fusion Monster', 'Warrior', 'LIGHT', 6, 2400, 1500, '属性不同的「元素英雄」怪兽×2 这张卡不用融合召唤不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，若对方场上的卡数量比自己场上的卡多则能发动。场上的其他卡全部破坏。 ②：把用通常怪兽为素材作融合召唤的这张卡解放，以自己墓地1只「元素英雄」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(9327502, 'Elemental HERO Voltic', '元素－英雄 伏特', 'E・HERO ボルテック', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1000, 1500, '①：这张卡给与对方战斗伤害时，以除外的1只自己的「元素英雄」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(55615891, 'Elemental HERO Wild Wingman', '元素英雄 荒野翼侠', 'E・HERO ワイルド・ウィングマン', 'Fusion Monster', 'Warrior', 'EARTH', 8, 1900, 2300, '「元素英雄 荒野侠」＋「元素英雄 羽翼侠」 这只怪兽不能作融合召唤以外的特殊召唤。可以丢弃1张手卡，把场上的1张魔法·陷阱卡破坏。'),
(10526791, 'Elemental HERO Wildedge', '元素－英雄 狂野锯刃人', 'E・HERO ワイルドジャギーマン', 'Fusion Monster', 'Warrior', 'EARTH', 8, 2600, 2300, '「元素英雄 荒野侠」＋「元素英雄 金刃侠」 这张卡不用融合召唤不能特殊召唤。 ①：这张卡可以向对方怪兽全部各作1次攻击。'),
(86188410, 'Elemental HERO Wildheart', '元素－英雄 狂野人', 'E・HERO ワイルドマン', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 1600, '①：这张卡只要在怪兽区域存在，不受陷阱卡的效果影响。'),
(75434695, 'Elemental HERO Woodsman', '元素－英雄 森林人', 'E・HERO フォレストマン', 'Effect Monster', 'Warrior', 'EARTH', 4, 1000, 2000, '①：1回合1次，自己准备阶段才能发动。选自己的卡组·墓地1张「融合」加入手卡。'),
(99414168, 'Elemental Mistress Doriado', '精灵术师 树精', '精霊術師 ドリアード', 'Ritual Effect Monster', 'Spellcaster', 'LIGHT', 3, 1200, 1400, '「树精的祈祷」降临。这张卡的属性也同时当作「风」「水」「炎」「地」使用。'),
(36586443, 'Elemental Recharge', '元素充能', 'エレメンタル・チャージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「元素英雄」的怪兽每有1只，自己回复1000基本分。'),
(11167052, 'Elemental Training', '灵神统一', '霊神統一', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的「灵神的圣殿」不会被效果破坏，不会成为对方的效果的对象。 ②：1回合1次，把自己场上1只怪兽解放才能发动。原本属性和解放的怪兽不同的1只「元素灵剑士」怪兽从卡组特殊召唤。 ③：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。手卡全部丢弃。那之后，从自己墓地选这个效果丢弃的卡数量的「灵神」怪兽加入手卡。'),
(300302048, 'Elements of Thunder, Water, and Wind', NULL, NULL, 'Skill Card', 'Paradox Broth', NULL, NULL, NULL, NULL, NULL),
(83032858, 'Elementsaber Aina', '元素灵剑士·辟地', 'エレメントセイバー・アイナ', 'Effect Monster', 'Warrior', 'EARTH', 2, 900, 1800, '①：1回合1次，从手卡把1只「元素灵剑士」怪兽送去墓地，以自己墓地1只「元素灵剑士·辟地」以外的「元素灵剑士」怪兽或者「灵神」怪兽为对象才能发动。那只怪兽无视召唤条件特殊召唤。 ②：这张卡在墓地存在的场合，1回合1次，宣言1个属性才能发动。墓地的这张卡直到回合结束时变成宣言的属性。'),
(18214905, 'Elementsaber Lapauila', '元素灵剑士·电光', 'エレメントセイバー・ラパウィラ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 400, 2100, '①：1回合1次，魔法·陷阱卡发动时，从手卡把1只「元素灵剑士」怪兽送去墓地才能发动。那个发动无效并破坏。 ②：这张卡在墓地存在的场合，1回合1次，宣言1个属性才能发动。墓地的这张卡直到回合结束时变成宣言的属性。'),
(71797713, 'Elementsaber Lapauila Mana', '元素灵剑士·金光', 'エレメントセイバー・ウィラード', 'Effect Monster', 'Warrior', 'LIGHT', 6, 2400, 2100, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡把2只其他怪兽送去墓地才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的「元素灵剑士」怪兽以及「灵神」怪兽受为这张卡的①的效果发动而送去墓地的「元素灵剑士」怪兽的原本属性对应的以下所适用。 ●地或者风：不会被战斗破坏。 ●水或者炎：不会被效果破坏。 ●光或者暗：不会成为对方的效果的对象。'),
(19036557, 'Elementsaber Makani', '元素灵剑士·随风', 'エレメントセイバー・マカニ', 'Effect Monster', 'Warrior', 'WIND', 2, 1300, 1200, '①：1回合1次，从手卡把1只「元素灵剑士」怪兽送去墓地才能发动。从卡组把「元素灵剑士·随风」以外的1只「元素灵剑士」怪兽或者「灵神」怪兽加入手卡。 ②：这张卡在墓地存在的场合，1回合1次，宣言1个属性才能发动。墓地的这张卡直到回合结束时变成宣言的属性。'),
(72819261, 'Elementsaber Malo', '元素灵剑士·日炙', 'エレメントセイバー・マロー', 'Effect Monster', 'Warrior', 'FIRE', 3, 1700, 200, '①：1回合1次，从手卡把1只「元素灵剑士」怪兽送去墓地才能发动。从卡组把「元素灵剑士·日炙」以外的1只「元素灵剑士」怪兽或者「灵神」怪兽送去墓地。 ②：这张卡在墓地存在的场合，1回合1次，宣言1个属性才能发动。墓地的这张卡直到回合结束时变成宣言的属性。'),
(45702014, 'Elementsaber Molehu', '元素灵剑士·幽暮', 'エレメントセイバー・モーレフ', 'Effect Monster', 'Warrior', 'DARK', 4, 1900, NULL, '①：1回合1次，从手卡把1只「元素灵剑士」怪兽送去墓地，以场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。这个效果在对方回合也能发动。 ②：这张卡在墓地存在的场合，1回合1次，宣言1个属性才能发动。墓地的这张卡直到回合结束时变成宣言的属性。'),
(46425662, 'Elementsaber Nalu', '元素灵剑士·波涛', 'エレメントセイバー・ナル', 'Effect Monster', 'Warrior', 'WATER', 3, 1500, 1000, '①：1回合1次，从手卡把1只「元素灵剑士」怪兽送去墓地，以自己墓地1只「元素灵剑士·波涛」以外的「元素灵剑士」怪兽或者「灵神」怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡在墓地存在的场合，1回合1次，宣言1个属性才能发动。墓地的这张卡直到回合结束时变成宣言的属性。'),
(85166216, 'Elephant Statue of Blessing', '恩惠之像', '恵みの像', 'Effect Monster', 'Rock', 'EARTH', 3, 1500, NULL, '当这张卡因对方控制的卡的效果从手卡被送去墓地时，自己回复2000基本分。'),
(12160911, 'Elephant Statue of Disaster', '灾厄之像', '災いの像', 'Effect Monster', 'Rock', 'EARTH', 3, 1500, NULL, '当这张卡因对方控制的卡的效果从手卡被送去墓地时，给与对方基本分2000分的伤害。'),
(88845345, 'Elephun', '飞象', 'エレファン', 'Tuner Monster', 'Beast', 'EARTH', 2, 500, 300, '这张卡被战斗破坏送去墓地时，可以选择从游戏中除外的1只自己的3星以下的兽族·兽战士族·鸟兽族怪兽加入手卡。'),
(39897277, 'Elf''s Light', '精灵之光', 'エルフの光', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '光属性的怪兽才能装备。装备的怪兽攻击力上升400，守备力下降200。'),
(85976588, 'Elfnote Fortuna', '耀圣之月诗 福尔图娜', '耀聖の月詩フォルトナ', 'Effect Monster', 'Spellcaster', 'LIGHT', 6, 2200, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：这张卡可以从手卡往自己的中央的主要怪兽区域特殊召唤。 ②：自己主要阶段才能发动。从手卡·卡组把1张「耀圣」永续陷阱卡在自己场上表侧表示放置。 ③：对方回合才能发动。自己的主要怪兽区域的这张卡和中央的怪兽的位置交换。那之后，可以让场上1张表侧表示的魔法·陷阱卡回到手卡。'),
(13597785, 'Elfnote Lucina', '耀圣之花诗 露西娜', '耀聖の花詩ルキナ', 'Effect Monster', 'Spellcaster', 'FIRE', 6, 2500, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：这张卡可以从手卡往自己的中央的主要怪兽区域特殊召唤。 ②：自己主要阶段才能发动。从卡组把「耀圣之花诗 卢西娜」以外的1只「耀圣」怪兽加入手卡。 ③：对方回合才能发动。自己的主要怪兽区域的这张卡和中央的怪兽的位置交换。那之后，可以让对方场上1只6星以下的怪兽回到手卡。'),
(12375297, 'Elfnote Power Patron', '煌耀圣诗之狱神精', '燿ける聖詩の獄神精', 'Tuner Monster', 'Fiend', 'FIRE', 1, 300, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：自己不是同调怪兽不能从额外卡组特殊召唤。 ②：自己·对方的主要阶段，以自己的中央的主要怪兽区域1只怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升3星。那之后，可以进行1只「耀圣」同调怪兽或「调狱神 朱诺拉」的同调召唤。 ③：这张卡作为同调素材送去墓地的场合才能发动。从卡组把1张「耀圣」卡加入手卡。'),
(56651978, 'Elfnote Regina', NULL, NULL, 'Effect Monster', 'Spellcaster', 'WIND', 6, 2000, 1800, NULL),
(42302563, 'Elfnote Seraphim Strelitzia', '狱花之大煌耀圣 斯特莉西亚', '獄花の大燿聖ストリチア', 'Synchro Monster', 'Plant', 'FIRE', 7, -1, 3000, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡只要在中央的主要怪兽区域存在，原本攻击力变成3000。 ②：自己·对方的主要阶段才能发动。从自己的手卡·墓地把1只6星以下的「耀圣」怪兽特殊召唤。那之后，可以让场上的全部4星以上的怪兽的等级直到回合结束时下降3星。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(59581480, 'Elfnote Tinia', '耀圣之波诗 蒂娜', '耀聖の波詩ディーナ', 'Effect Monster', 'Spellcaster', 'WATER', 6, 2400, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：这张卡可以从手卡往自己的中央的主要怪兽区域特殊召唤。 ②：自己主要阶段才能发动。从卡组把1张「耀圣」永续魔法卡在自己场上表侧表示放置。 ③：对方回合才能发动。自己的主要怪兽区域的这张卡和中央的怪兽的位置交换。那之后，可以把对方手卡随机选1张直到结束阶段表侧除外。'),
(90880453, 'Elfnotes: A Plea for Help', '耀圣诗章～再会的三重唱～', 'エルフェンノーツ～再邂のテルチェット～', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方不能把自己的中央的主要怪兽区域的怪兽作为效果的对象。 ②：自己的中央的主要怪兽区域的怪兽属性让这张卡得到以下效果。 ●炎·地：自己的同调怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ●水·风：自己场上的其他的表侧表示的魔法·陷阱卡不会被对方的效果破坏。 ●光·暗：自己受到的战斗伤害变成0。'),
(50590801, 'Elfnotes: Aristeia of Trust', '耀圣诗章～托选之武功歌～', 'エルフェンノーツ～託選のアリスティア～', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次，①②的效果在同一连锁上不能发动。 ①：1回合1次，以自己场上1只表侧表示怪兽为对象才能发动。那只自己怪兽的位置向其他的自己的主要怪兽区域移动。 ②：自己场上有「耀圣」怪兽3只以上存在，对方把魔法·陷阱卡发动时才能发动。那个效果无效。自己场上有同调怪兽存在的场合，可以再把那张无效的卡破坏。'),
(24092792, 'Elfnotes: Rhapsodia of Madness', '耀圣诗章～激奏之狂想曲～', 'エルフェンノーツ～狂奏のラプソディア～', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己的中央的主要怪兽区域有怪兽存在，对方怪兽只能向那只怪兽攻击。 ②：从自己的手卡·场上把1只怪兽送去墓地，以原本属性和那只怪兽不同的自己墓地1只「耀圣」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，自己场上有同调怪兽存在的场合，可以把对方场上1张表侧表示卡的效果直到回合结束时无效。'),
(64491754, 'Elfnotes: Welcome Home', '耀圣诗章～归乡之排比句～', 'エルフェンノーツ～廻郷のパラレリズム～', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己的中央的主要怪兽区域的怪兽不会被效果破坏。 ②：从自己的手卡·场上把1只怪兽送去墓地才能发动。原本属性和那只怪兽不同的1只「耀圣」怪兽从卡组守备表示特殊召唤。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(73872164, 'Eliminating the League', '家破人亡', 'お家おとりつぶし', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1张魔法卡，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽破坏。那之后，有对方手卡的场合，把对方手卡确认，破坏的卡的同名卡全部送去墓地。'),
(60292055, 'Elphase', '相位精灵', 'エルフェーズ', 'Link Monster', 'Cyberse', 'WIND', NULL, 2000, NULL, '3星以上的电子界族怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡所连接区的怪兽数量×300。 ②：连接召唤的表侧表示的这张卡从场上离开的场合，以自己墓地1只4星以下的电子界族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合效果无效化，不能作为连接素材。'),
(101303071, 'Elvennotes ~Oracle Alicetea~', '耀圣诗章～托选之武功歌～', 'エルフェンノーツ～託選のアリスティア～', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
(101304014, 'Elvennotes Regina', '耀圣之风诗 蕾吉娜', '耀聖の風詩レギナ', 'Effect Monster', 'Spellcaster', 'WIND', 6, 2000, 1800, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己·对方回合，从自己的手卡·场上（表侧表示）把这张卡以外的1张「耀圣」卡送去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡在中央的主要怪兽区域召唤·特殊召唤的场合才能发动。从卡组把「耀圣之风诗 蕾吉娜」以外的1只「耀圣」怪兽特殊召唤。 ③：这张卡作为同调素材送去墓地的场合才能发动。这张卡加入手卡。'),
(61980241, 'Elzette of the White Forest', '白森的莉塞特', '白き森のリゼット', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。这张卡从手卡特殊召唤。那之后，从卡组把「白森林的莉泽特」以外的1只「白森林」怪兽加入手卡。 ②：这张卡在墓地存在的状态，对方回合自己场上有魔法师族·光属性调整特殊召唤的场合才能发动。这张卡加入手卡。'),
(38648860, 'Elzette, Azamina of the White Forest', '白森的圣徒 莉塞特', '白き森の聖徒リゼット', 'Effect Monster', 'Illusion', 'LIGHT', 2, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从手卡把1只「白森林」怪兽或「蓟花」怪兽特殊召唤。 ②：自己主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「蓟花」融合怪兽融合召唤。 ③：这张卡作为同调素材送去墓地的场合才能发动。从卡组把1张「罪宝」卡加入手卡。'),
(48017189, 'EM:P Meowmine', 'EM：P猫猫手榴弹', 'EM：Pグレニャード', 'Effect Monster', 'Cyberse', 'DARK', 2, 800, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场上或者自己或对方的墓地有连接怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡在手卡·墓地存在，自己场上的连接2怪兽被送去墓地的场合或者被表侧除外的场合，把这张卡除外，以对方场上1张卡为对象才能发动。那张卡回到手卡。'),
(35035985, 'Embers of the Ashened', '灰灭之末路', '灰滅せし成れの果て', 'Fusion Monster', 'Pyro', 'DARK', 8, 2900, 2400, '炎族怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合，以自己墓地1张场地魔法卡为对象才能发动。那张卡加入手卡。 ②：这张卡和对方的炎族怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽破坏。这个效果在自己回合发动的场合，这张卡只再1次可以继续攻击。'),
(6390406, 'Emblem of Dragon Destroyer', '龙破坏之证', '竜破壊の証', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的卡组·墓地选1只「破坏之剑士」加入手卡。'),
(9845733, 'Emblem of the Awakening', '觉醒之证', '覚醒の証', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「觉醒战士 库丘林」的降临必需。必须从手卡·自己场上把等级合计直到4以上的怪兽解放。'),
(80621422, 'Emblem of the Plunder Patroll', '海造贼-象征', '海造賊－象徴', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「海造贼」怪兽才能装备。这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽的攻击力上升500，不会成为对方的效果的对象。 ②：把装备的这张卡送去墓地才能发动。把持有和双方的场上·墓地的怪兽的其中任意种相同属性的1只「海造贼」怪兽从额外卡组特殊召唤。那之后，这张卡装备过的怪兽给那只特殊召唤的怪兽当作攻击力上升500的装备卡使用来装备。'),
(77765207, 'Emblema Oath', '起誓的徽纹', '誓いのエンブレーマ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从卡组把1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。这个回合，这个效果放置的卡或者原本卡名和那张卡相同的卡在自己场上表侧表示存在期间，自己不是「百夫长骑士」怪兽不能从额外卡组特殊召唤。 ●从卡组把1张「百夫长骑士」魔法·陷阱卡在自己场上盖放。'),
(61950680, 'Emblema Salvation', '赎罪的徽纹', '贖いのエンブレーマ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己的魔法与陷阱区域1张表侧表示的「百夫长骑士」怪兽卡除外，以对方场上1张卡为对象才能发动。那张卡除外。 ②：盖放的这张卡被对方的所发动的效果所破坏的场合或者所除外的场合才能发动。自己的手卡·卡组·墓地·除外状态的2只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置（同名卡最多1张）。'),
(28649820, 'Embodiment of Apophis', '阿波菲斯的化神', 'アポピスの化神', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己·对方的主要阶段才能把这张卡发动。这张卡变成通常怪兽（爬虫类族·地·4星·攻1600/守1800）在怪兽区域特殊召唤（也当作陷阱卡使用）。'),
(59069885, 'Embrace of the Tistina', '提斯蒂娜的拥抱', 'ティスティナの抱擁', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，若非自己场上有守备力3000以上的「提斯蒂娜」怪兽存在的场合则不能发动。 ①：对方把场上的怪兽的效果发动时，以那1只怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ②：自己·对方的结束阶段，以对方场上1只里侧守备表示怪兽为对象才能发动。得到那只怪兽的控制权。'),
(64154377, 'Embryonic Beast', '未熟的恶魔', '未熟な悪魔', 'Normal Monster', 'Fiend', 'DARK', 2, 500, 750, '还没成为完全体的丑恶魔。肚子上的洞会吸入任何东西。'),
(43633088, 'Emergency Apport', '紧急物体显形', '緊急アポート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己的墓地·除外状态的1只5星以下的念动力族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(24019261, 'Emergency Assistance', '救急救命', '救急救命', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '主要阶段2才能发动。这个回合被卡的效果破坏送去墓地的1只4星的怪兽从自己墓地特殊召唤。'),
(53046408, 'Emergency Provisions', '非常食', '非常食', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把这张卡以外的自己场上的魔法·陷阱卡任意数量送去墓地才能发动。自己回复因为这张卡发动而送去墓地的卡数量×1000基本分。'),
(67723438, 'Emergency Teleport', '紧急瞬移', '緊急テレポート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从手卡·卡组把1只3星以下的念动力族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段除外。'),
(61292243, 'EMERGENCY!', '紧急！', 'EMERGENCY！', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「救援ACE队」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「救援ACE队」怪兽守备表示特殊召唤。那之后，自己的手卡·场上1只「救援ACE队」怪兽解放。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1张「救援ACE队」陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(70628672, 'Emergeroid Call', '红色机人呼唤', 'レッド・ロイド・コール', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有「机人」融合怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效。那之后，从发动的那个玩家的卡组·额外卡组把同名卡全部送去墓地。 ②：把墓地的这张卡除外，以自己墓地1只「机人」怪兽为对象才能发动。那只怪兽加入手卡。'),
(97926515, 'Emerging Emergency Rescute Rescue', '紧急救急救命救援', '緊急救急救命レスキュー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己基本分比对方少的场合才能发动。从卡组把3只攻击力300/守备力100的兽族怪兽给对方观看，对方从那之中选1只。那1只怪兽加入自己手卡，剩余回到卡组。'),
(43580269, 'Emes the Infinity', '无限真理', 'エメス・ザ・インフィニティ', 'Effect Monster', 'Machine', 'LIGHT', 7, 2500, 2000, '①：这张卡战斗破坏对方怪兽送去墓地的场合发动。这张卡的攻击力上升700。'),
(87003671, 'Emilia, Dance Priestess of the Nekroz', '影灵衣的舞巫女 艾米莉娅', '影霊衣の舞巫女 エミリア', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1600, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的场上或墓地有战士族「影灵衣」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只「影灵衣」仪式怪兽或1张「影灵衣」魔法卡加入手卡。 ③：「影灵衣」仪式怪兽1只仪式召唤的场合，可以由自己场上的这1张卡作为仪式召唤需要的数值的解放使用。'),
(42685062, 'Emissary from Pandemonium', '来自地狱的使者', '地獄からの使い', 'Tuner Monster', 'Fiend', 'EARTH', 7, 2600, 1800, '这张卡不能特殊召唤。这张卡可以把1只怪兽解放作召唤。这个方法召唤的这张卡的等级变成5星，原本的攻击力·守备力变成一半数值。'),
(87462901, 'Emissary from the House of Wax', '幻蜡馆的使者', '幻蝋館の使者', 'Effect Monster', 'Illusion', 'FIRE', 3, 800, 1800, '这个卡名的①的效果1回合只能使用1次。 ①：对方怪兽的攻击宣言时才能发动。这张卡从手卡特殊召唤。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：对方战斗阶段结束时才能发动。对方场上的全部攻击表示怪兽直到下次的对方战斗阶段开始时不能把表示形式变更，不能作为融合·同调·超量·连接召唤的素材，效果无效化。'),
(44330099, 'Emissary of Darkness Token', '冥府之使者格斯', '冥府の使者ゴーズ', 'Token', 'Fairy', NULL, NULL, NULL, NULL, NULL),
(75043725, 'Emissary of the Afterlife', '冥界的使者', '冥界の使者', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 600, '当这张卡从场上被送去墓地时，各自从自己的卡组中选择1张3星以下的通常怪兽，相互确认之后分别加入手卡。'),
(6103294, 'Emissary of the Oasis', '绿洲的使者', 'オアシスの使者', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 600, 400, '当自己场上存在表侧表示的3星以下的通常怪兽时，对方不能选择这张卡作为攻击对象。当这张卡在自己场上以表侧表示存在时，这张卡的控制者所受到的，由3星以下的通常怪兽进行战斗所造成的战斗伤害为零。'),
(97864322, 'Emperor Charles the Great', '查理大帝', 'シャルル大帝', 'Link Monster', 'Warrior', 'FIRE', NULL, 3000, NULL, '有装备卡装备的9星「焰圣骑士帝-查理」1只 ①：这张卡连接召唤的场合，以自己墓地1只「焰圣骑士帝-查理」为对象才能发动。这张卡当作和那张卡同名卡使用，得到相同效果。那之后，作为对象的怪兽当作攻击力上升500的装备魔法卡使用给这张卡装备。 ②：1回合1次，魔法·陷阱卡的效果发动时，从自己的手卡·场上（表侧表示）把1张装备魔法卡送去墓地才能发动。那个发动无效并破坏。'),
(33022867, 'Emperor Maju Garzett', '魔兽皇帝 加泽特', '魔獣皇帝ガーゼット', 'Effect Monster', 'Fiend', 'DARK', 9, NULL, NULL, '这张卡不能通常召唤。把自己场上3只怪兽解放的场合才能特殊召唤。 ①：这张卡的攻击力变成因为这张卡特殊召唤而解放的怪兽的原本攻击力合计数值。 ②：只要这张卡在怪兽区域存在，对方在战斗阶段中不能把魔法·陷阱·怪兽的效果发动。'),
(501000007, 'Emperor of Lightning', NULL, NULL, 'Effect Monster', 'Thunder', 'LIGHT', 8, 2600, 2600, NULL),
(53136004, 'Emperor of Prophecy', '魔导皇士 安普尔', '魔導皇士 アンプール', 'Effect Monster', 'Spellcaster', 'DARK', 5, 2300, 2000, '把这张卡以外的自己场上表侧表示存在的1只魔法师族怪兽和自己墓地1张名字带有「魔导书」的卡从游戏中除外才能发动。选择对方场上表侧表示存在的1只怪兽直到结束阶段时得到控制权。「魔导皇士 安普尔」的效果1回合只能使用1次，这个效果发动的回合，这张卡不能攻击。'),
(11250655, 'Emperor of the Land and Sea', '水陆的帝王', '水陸の帝王', 'Normal Monster', 'Reptile', 'WATER', 5, 1800, 1500, '可以用大嘴向四方喷火的爬虫怪。'),
(21672573, 'Emperor Sem', '帝尸神官', 'エンペラー・ストゥム', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1300, 2200, '只要这张卡在自己场上表侧表示存在，自己对怪兽的上级召唤成功时，双方玩家可以选择各自墓地存在的1张卡回到卡组最上面。'),
(20560620, 'Emperor Tanuki''s Critter Count', '狸猫大人换天子', 'お代狸様の代算様', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, 1600, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，这张卡不能解放。 ②：只要这张卡在怪兽区域存在，自己把怪兽仪式召唤的场合，自己的额外卡组1只怪兽也能作为解放的代替而送去墓地。'),
(54250060, 'Empowerment', '召魔装着', '召魔装着', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的龙族·战士族·魔法师族怪兽的攻击力·守备力上升300。 ②：1回合1次，丢弃1张手卡才能发动。从卡组把1只「魔装战士」怪兽特殊召唤。 ③：1回合1次，把自己墓地的战士族·魔法师族怪兽合计4只除外才能发动。从卡组把1只「以太神兵龙」怪兽加入手卡。'),
(15237615, 'Empress Judge', '下裁决的女帝', '裁きを下す女帝', 'Fusion Monster', 'Warrior', 'EARTH', 6, 2100, 1700, '「女王的影武者」＋「响女」'),
(58818411, 'Empress Mantis', '女帝螳螂', '女帝カマキリ', 'Normal Monster', 'Insect', 'WIND', 6, 2200, 1400, '领导力卓越的巨大螳螂女王。无论移动还是狩猎，螳螂大军都听从她的命令。'),
(770365, 'Empress of Prophecy', '魔导皇圣 特莉丝', '魔導皇聖 トリス', 'XYZ Monster', 'Spellcaster', 'LIGHT', 5, 2000, 1700, '魔法师族5星怪兽×2 这张卡的攻击力上升自己场上的超量素材数量×300的数值。此外，1回合1次，把这张卡1个超量素材取除才能发动。把自己卡组洗切。那之后，从卡组上面把5张卡翻开，选最多有那之中的名字带有「魔导书」的卡数量的场上的怪兽破坏。那之后，翻开的卡用喜欢的顺序回到卡组上面。'),
(9409625, 'Empty Machine', '虚无械', '虚無械アイン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡只在场上表侧表示存在才有1次不会被对方的效果破坏。 ②：1回合1次，可以从以下效果选择1个发动。 ●从手卡丢弃1只10星怪兽才能发动。自己从卡组抽1张。 ●自己的魔法与陷阱区域没有这张卡以外的卡存在的场合，以自己墓地1只「时械神」怪兽为对象才能发动。那只怪兽回到卡组。那之后，可以从手卡·卡组选1张「无限械」在自己的魔法与陷阱区域盖放。'),
(80170678, 'EN - Engage Neo Space', 'EN－交战新宇空间', 'EN－エンゲージ・ネオスペース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ①：把1只「新空间侠」怪兽和1只「元素英雄」怪兽从手卡以及卡组各1只送去墓地才能发动。从卡组把1只「新空间侠」怪兽或者5星以上的「元素英雄」怪兽特殊召唤，从自己的卡组·墓地选1张「融合」加入手卡。这个效果特殊召唤的怪兽是「元素英雄 新宇侠」的场合，那个攻击力上升1000。'),
(10186633, 'EN Shuffle', 'EN洗牌', 'ENシャッフル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：选自己场上1只「元素英雄」怪兽或者「新空间侠」怪兽回到持有者卡组，和那只怪兽卡名不同的1只「元素英雄」怪兽或者「新空间侠」怪兽从卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。从自己墓地选「元素英雄」怪兽和「新空间侠」怪兽各1只或者「元素英雄 新宇侠」1只回到卡组。那之后，自己从卡组抽1张。'),
(89058026, 'EN Wave', 'EN波动', 'ENウェーブ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的「元素英雄」怪兽成为融合怪兽的融合召唤的素材，被送去墓地的场合或者被除外的场合才能发动。从卡组把1只「新空间侠」怪兽或者「元素英雄 新宇侠」特殊召唤。 ②：「新空间侠」怪兽或者「元素英雄 新宇侠」从自己的场上·墓地回到自己的卡组·额外卡组的场合才能发动。从自己墓地选1只「元素英雄」怪兽特殊召唤。'),
(55965529, 'Enato Enneacraft - "oknirIA"', '纠罪巧θ’－怠惰“oknirIA”', '糾罪巧θ’－「oknirIA」', 'Pendulum Flip Effect Monster', 'Machine', 'EARTH', 1, 100, 1000, '①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不用里侧守备表示不能把怪兽特殊召唤）。从手卡把1只怪兽里侧守备表示特殊召唤。 ②：墓地·除外状态的卡的效果由对方发动时，把里侧表示的这张卡变成表侧守备表示才能发动。从卡组把1张「纠罪巧」卡加入手卡。 ③：这张卡反转的场合发动。对方的墓地·除外状态的最多3张卡回到卡组。'),
(96355986, 'Enchanted Javelin', '神圣标枪', 'ホーリージャベリン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。自己基本分回复那1只攻击怪兽的攻击力的数值。'),
(30531525, 'Enchanting Fitting Room', '魔之试衣间', '魔の試着部屋', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付800基本分。翻开自己卡组最上面4张卡，将其中3星以下的通常怪兽特殊召唤到自己场上，将翻开的其它卡回到卡组。'),
(75376965, 'Enchanting Mermaid', '恍惚人鱼', '恍惚の人魚', 'Normal Monster', 'Fish', 'WATER', 3, 1200, 900, '诱惑在海上航行的人们并将他们淹死的美人鱼。'),
(6622715, 'Encode Talker', '编码语者', 'エンコード・トーカー', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 2300, NULL, '电子界族怪兽2只以上 ①：1回合1次，这张卡所连接区的自己怪兽和比那只怪兽攻击力高的对方怪兽进行战斗的伤害计算前才能发动。那只自己怪兽不会被那次战斗破坏，那次战斗发生的对自己的战斗伤害变成0。那次伤害计算后，选这张卡或者这张卡所连接区1只自己怪兽，那个攻击力直到回合结束时上升那只进行战斗的对方怪兽的攻击力数值。'),
(53442500, 'End of the Line', '走魔灯', '走魔灯', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己基本分未满100的场合才能发动。自己从卡组抽2张。自己基本分未满10的场合，再让自己从卡组抽2张。'),
(8198712, 'End of the World', '世界终灭', 'エンド・オブ・ザ・ワールド', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放，从手卡把「破灭之女神 露茵」或「终焉之王 迪米斯」仪式召唤。'),
(3739500, 'End of the World Ruler', '世界终灭支配者', '破滅と終焉の支配者', 'Ritual Effect Monster', 'Fiend', 'DARK', 10, 3000, 2900, '「世界末日」卡降临 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在手卡·场上存在当作「终焉之王 迪米斯」使用。 ②：把手卡的这张卡给对方观看，支付2000基本分，从卡组把1张仪式魔法卡除外才能发动。那张仪式魔法卡发动时的仪式召唤效果适用。 ③：支付2000基本分才能发动。场上的其他卡全部破坏。那之后，这张卡的攻击力上升2900。'),
(35989913, 'Endless Bond', '永远之绊', '永遠の絆', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「超量」卡使用。这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从自己墓地把1只「No.39 希望皇 霍普」特殊召唤。那只怪兽的攻击力上升自己墓地的光属性「霍普」超量怪兽的攻击力的合计数值。 ②：原本属性是光属性的自己的「霍普」超量怪兽的攻击破坏对方怪兽时才能发动。那只自己怪兽的攻击力下降1000，那只怪兽可以继续攻击。'),
(7845138, 'Endless Decay', '茫漠的死者', '茫漠の死者', 'Effect Monster', 'Zombie', 'DARK', 5, -1, NULL, '①：自己基本分是2000以下的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合发动。这张卡的攻击力变成对方基本分一半的数值。'),
(21887075, 'Endless Engine Argyro System', '无尽机关 阿尔银洛系统', '無尽機関アルギロ・システム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1张「兽带斗神」卡送去墓地。 ②：这张卡在墓地存在的场合，以自己墓地1张「兽带斗神」卡为对象才能发动。那张卡和这张卡之内1张加入手卡，另1张回到卡组最下面。'),
(300302007, 'Endless Traps', NULL, NULL, 'Skill Card', 'Odion', NULL, NULL, NULL, NULL, NULL),
(34041788, 'Endymion Empire', '恩底弥翁皇国', 'エンディミオン皇国', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，把1只「圣月之皇太子 雷古勒斯」或者有那个卡名记述的怪兽从卡组加入手卡。对方场上有怪兽存在的场合，可以再从手卡把1只魔法师族怪兽特殊召唤。 ②：自己场上的卡被战斗·效果破坏的场合，可以作为代替把自己的手卡·场上（表侧表示）1只「圣月之皇太子 雷古勒斯」破坏。'),
(20714553, 'Endymion, the Crescent of Magistus', '圣月之伟魔导士 恩底弥翁', '聖月の魔導士エンディミオン', 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 1850, NULL, '包含魔法师族·4星怪兽的怪兽2只 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡连接召唤的场合，以自己场上1只「大贤者」怪兽为对象才能发动。自己的墓地·除外状态的1只魔法师族怪兽当作装备魔法卡使用给作为对象的怪兽装备。 ②：自己·对方的主要阶段，以自己的魔法与陷阱区域1张当作装备魔法卡使用的魔法师族怪兽卡为对象才能发动。那张卡回到手卡。'),
(9482987, 'Endymion, the Magistus of Mastery', '伟魔贤者 圣魔之恩底弥翁', '聖魔の大賢者エンディミオン', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1300, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「大贤者」怪兽为对象才能发动。从额外卡组选1只「大贤者」怪兽当作装备卡使用给作为对象的怪兽装备。 ②：以自己场上1张表侧表示的魔法卡为对象才能发动。那张卡破坏，自己从卡组抽1张。那之后，选1张手卡回到卡组最下面。'),
(40732515, 'Endymion, the Master Magician', '神圣魔导王 恩底弥翁', '神聖魔導王 エンディミオン', 'Effect Monster', 'Spellcaster', 'DARK', 7, 2700, 1700, '①：这张卡可以把自己场上的「魔法都市 恩底弥翁」放置的6个魔力指示物取除，从手卡·墓地特殊召唤。 ②：这张卡的①的方法特殊召唤成功的场合，以自己墓地1张魔法卡为对象发动。那张卡加入手卡。 ③：1回合1次，从手卡丢弃1张魔法卡，以场上1张卡为对象才能发动。那张卡破坏。'),
(3611830, 'Endymion, the Mighty Master of Magic', '创圣魔导王 恩底弥翁', '創聖魔導王 エンディミオン', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 7, 2800, 1700, '①：1回合1次，魔法·陷阱卡的效果发动时才能发动。选自己场上1张有魔力指示物放置的卡回到持有者手卡，那个发动无效并破坏。那之后，可以把回到手卡的那张卡放置的数量的魔力指示物给这张卡放置。 ②：有魔力指示物放置的这张卡不会成为对方的效果的对象，不会被对方的效果破坏。 ③：有魔力指示物放置的这张卡被战斗破坏时才能发动。从卡组把1张通常魔法卡加入手卡。'),
(65342096, 'Endymion''s Lab', '恩底弥翁的实验设施', '魔法都市の実験施設', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡只要在魔法与陷阱区域存在，卡名当作「魔法都市 恩底弥翁」使用。 ②：每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ③：1回合1次，自己的魔法师族怪兽被战斗破坏的伤害计算后，把自己场上6个魔力指示物取除才能发动。从手卡·卡组把1只7星以上的魔法师族怪兽特殊召唤。'),
(98045062, 'Enemy Controller', '敌人控制器', 'エネミーコントローラー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。 ●以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽的表示形式变更。 ●把自己场上1只怪兽解放，以对方场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽的控制权直到结束阶段得到。'),
(300302029, 'Energizing Elements', NULL, NULL, 'Skill Card', 'Bastion Misaw', NULL, NULL, NULL, NULL, NULL),
(72631243, 'Energy Bravery', '能量勇士', 'エナジー・ブレイブ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1200, '只要这张卡在自己场上表侧表示存在，自己场上存在的再度召唤状态的二重怪兽不会被卡的效果破坏。'),
(56916805, 'Energy Drain', '能量吸收', 'エナジー・ドレイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只以表侧表示存在的怪兽。此怪兽的攻击力·守备力上升对方手卡数量×200点的数值直到结束阶段为止。'),
(57006589, 'Energy-Absorbing Monolith', '能量吸收板', 'エネルギー吸収板', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '给与自己伤害的魔法·陷阱·效果怪兽的效果由对方发动时才能发动。自己作为受到伤害的代替而回复那个数值的基本分。'),
(26022485, 'Enervating Mist', '衰弱之雾', '衰弱の霧', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方手卡数量限制变成最多5张。'),
(82556059, 'Engine Token', '恶性马达・欧米伽', 'デモニック・モーター・Ω', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(50078320, 'Engraver of the Mark', '刻印之调停者', '刻印の調停者', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 1200, '①：对方把宣言1个卡名发动的效果发动时，把这张卡从手卡送去墓地才能发动。宣言1个卡名。对方宣言的卡名变成这个效果宣言的卡名。 ②：1回合1次，以场上1张表侧表示的卡为对象才能发动。下个回合的结束阶段把那张卡破坏。这个效果在对方回合也能发动。'),
(72444406, 'Enigmaster Packbit', '谜码圣手・封元', 'エニグマスター・パックビット', 'Synchro Monster', 'Cyberse', 'WATER', 8, 2900, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合或者被送去墓地的场合，以自己墓地或对方场上（表侧表示）1只怪兽为对象才能发动。选自己1张手卡丢弃，作为对象的怪兽当作永续陷阱卡使用在原本持有者的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续陷阱卡使用的场合，自己·对方回合可以发动。自己的魔法与陷阱区域1张表侧表示的怪兽卡特殊召唤。'),
(38280762, 'Enishi, Shien''s Chancellor', '紫炎的老中 缘', '紫炎の老中 エニシ', 'Effect Monster', 'Warrior', 'LIGHT', 6, 2200, 1200, '这张卡不能通常召唤。把自己墓地2只名字带有「六武众」的怪兽从游戏中除外的场合才能特殊召唤。1回合1次，可以选择场上表侧表示存在的1只怪兽破坏。这个效果发动的回合，这张卡不能攻击宣言。'),
(57274196, 'Enlightenment', '未来王的预言', '未来王の予言', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的魔法师族怪兽的攻击破坏对方怪兽的场合，那个伤害步骤结束时才能发动。那只怪兽只有1次可以继续攻击。这张卡发动的回合，自己不能召唤·反转召唤·特殊召唤。'),
(46186135, 'Enlightenment Dragon', '神光之龙', '神光の龍', 'Fusion Monster', 'Dragon', 'LIGHT', 10, 3000, 3000, '「裁决之龙」＋「惩戒之龙」 从自己的场上以及墓地各把1只上记的卡除外的场合才能特殊召唤。 ①：自己·对方回合1次，支付2000基本分才能发动。这张卡以外的双方的场上·墓地的卡全部除外。 ②：自己结束阶段发动。从自己卡组上面把4张卡送去墓地。 ③：这张卡被对方破坏的场合才能发动。自己的除外状态的「裁决之龙」「惩戒之龙」各1只加入手卡。那之后，可以把那2只无视召唤条件特殊召唤。'),
(59123194, 'Enlightenment Paladin', '觉醒的魔导剑士', '覚醒の魔導剣士', 'Synchro Monster', 'Spellcaster', 'DARK', 8, 2500, 2000, '调整＋调整以外的怪兽1只以上 「觉醒之魔导剑士」的①的效果1回合只能使用1次。 ①：「魔术师」灵摆怪兽作为素材让这张卡同调召唤成功的场合，以自己墓地1张魔法卡为对象才能发动。那张卡加入手卡。 ②：这张卡战斗破坏对方怪兽时才能发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(74820316, 'Enlilgirsu, the Orcust Mekk-Knight', '宵星之自鸣天琴・机界骑士 恩基苏', '宵星の騎士エンリルギルス', 'Link Monster', 'Machine', 'DARK', NULL, 2600, NULL, '包含「自奏圣乐」连接怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以自己的除外状态的1张「自奏圣乐」卡或「星遗物」卡为对象才能发动。那张卡加入手卡。那之后，可以选自己1张手卡回到卡组并得到对方场上1只表侧表示怪兽的控制权。 ②：这张卡从额外怪兽区域送去墓地的回合的自己主要阶段，把这张卡除外才能发动。场上1张卡送去墓地。'),
(32120116, 'Enma''s Judgment', '阎魔的裁决', '閻魔の裁き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方对怪兽的特殊召唤成功时才能发动。那些怪兽破坏。那之后，以下效果可以适用。 ●从自己墓地把5只不死族怪兽除外，从手卡·卡组把1只7星以上的不死族怪兽特殊召唤。'),
(82359538, 'Enneacraft - Aiza.LEON', '纠罪巧－骄狮 Aizaβ.LEON', '糾罪巧－Aizaβ.LEON', 'Pendulum Flip Effect Monster', 'Machine', 'LIGHT', 9, 3000, 2500, '①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不用里侧守备表示不能把怪兽特殊召唤）。从手卡把1只怪兽里侧守备表示特殊召唤。 ②：对方连锁自己的效果的发动把卡的效果发动时，把里侧表示的这张卡变成表侧守备表示才能发动。场上最多3张卡回到手卡。 ③：只要反转过的这张卡在怪兽区域存在，对方每次自身的卡的效果让自身手卡有卡加入，受到每1张900伤害。'),
(81237046, 'Enneacraft - Archa.TAIL', '纠罪巧－嗜蝎 Archaη.TAIL', '糾罪巧－Archaη.TAIL', 'Pendulum Flip Effect Monster', 'Machine', 'LIGHT', 9, 3000, 2500, '①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不用里侧守备表示不能把怪兽特殊召唤）。从手卡把1只怪兽里侧守备表示特殊召唤。 ②：要让场上的卡破坏的效果由对方发动时，把里侧表示的这张卡变成表侧守备表示才能发动。这个回合中，自己场上的怪兽以及「纠罪巧」魔法卡不会被效果破坏。 ③：只要反转过的这张卡在怪兽区域存在，每次怪兽被送去对方墓地，对方受到900伤害。'),
(28454232, 'Enneacraft - Asta.PIXEA', '纠罪巧－诈狐 Astaγ.PIXIEA', '糾罪巧－Astaγ.PIXIEA', 'Pendulum Flip Effect Monster', 'Machine', 'LIGHT', 9, 3000, 2500, '①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不用里侧守备表示不能把怪兽特殊召唤）。从手卡把1只怪兽里侧守备表示特殊召唤。 ②：自己场上的卡为对象的效果由对方发动时，把里侧表示的这张卡变成表侧守备表示才能发动。那个效果无效。那之后，可以把对方手卡随机1张里侧除外。 ③：只要反转过的这张卡在怪兽区域存在，对方不能把场上·墓地的卡作为效果的对象。'),
(71801447, 'Enneacraft - Atil.SPIA', NULL, NULL, 'Pendulum Flip Effect Monster', 'Machine', 'LIGHT', 9, 3000, 2500, NULL),
(54842941, 'Enneacraft - Atori.MAR', '纠罪巧－惧鲸 Atoriϝ.MAR', '糾罪巧－Atoriϝ.MAR', 'Pendulum Flip Effect Monster', 'Machine', 'LIGHT', 9, 3000, 2500, '①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不用里侧守备表示不能把怪兽特殊召唤）。从手卡把1只怪兽里侧守备表示特殊召唤。 ②：自己回合对方在场上把卡的效果发动时，把里侧表示的这张卡变成表侧守备表示才能发动。那个发动无效并破坏。 ③：这张卡反转的场合发动。对方场上的怪兽全部变成里侧守备表示。这个效果变成里侧守备表示的怪兽不能把表示形式变更。'),
(54020393, 'Enneacraft Release', '纠罪巧－解放始导', '糾罪巧－始導', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「纠罪巧」灵摆怪兽在自己的灵摆区域放置。 ②：把这个回合没有送去墓地的这张卡从墓地除外才能发动。从自己的额外卡组（表侧）把1只「纠罪巧」怪兽加入手卡。'),
(19504025, 'Enneacraft Reset', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(80015408, 'Enneacraft Reverth', '纠罪巧－反转裁诞', '糾罪巧－裁誕', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上（表侧表示）让「纠罪巧」怪兽卡任意数量回到卡组。那之后，自己抽出回去的数量。 ②：这张卡在墓地存在的状态，对方把怪兽召唤·特殊召唤的场合，可以把这张卡除外，从以下效果选择1个发动。 ●从手卡把1只「纠罪巧」怪兽里侧守备表示特殊召唤。 ●自己场上1只里侧守备表示的「纠罪巧」怪兽变成表侧守备表示。'),
(17621695, 'Enneapolis', '纠罪都市', '糾罪都市－エニアポリス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「纠罪巧」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上的「纠罪巧」灵摆怪兽卡任意数量为对象才能发动。那些卡回到手卡。 ②：自己场上的「纠罪巧」灵摆怪兽在主要阶段反转的场合才能发动。选那之内的1只回到手卡或在自己的灵摆区域放置。 ③：自己·对方的结束阶段发动。自己场上的纠罪指示物全部取除，对方受到那个数量×900伤害。'),
(76909279, 'Enraged Battle Ox', '激昂的牛头人', '激昂のミノタウルス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1700, 1000, '①：只要这张卡在怪兽区域存在，自己的兽族·兽战士族·鸟兽族怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(91862578, 'Enraged Muka Muka', '激昂的姆卡姆卡', '激昂のムカムカ', 'Effect Monster', 'Rock', 'EARTH', 5, 1200, 600, '自己每有1张手卡，这张卡攻击力·守备力各上升400。'),
(38695361, 'Envoy of Chaos', '混沌的使者', '混沌の使者', 'Effect Monster', 'Warrior', 'DARK', 4, 1500, NULL, '①：自己·对方的战斗阶段把这张卡从手卡丢弃，以自己场上1只「混沌战士」怪兽或者「暗黑骑士 盖亚」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1500，这个回合和那只怪兽进行战斗的对方怪兽的攻击力只在伤害计算时变成原本攻击力。 ②：自己·对方的结束阶段有这张卡在墓地存在的场合，从自己墓地把这张卡以外的光属性和暗属性的怪兽各1只除外才能发动。这张卡加入手卡。'),
(51611041, 'Epigonen, the Impersonation Invader', '模拘摄星人 模仿者', '模拘撮星人 エピゴネン', 'Effect Monster', 'Rock', 'LIGHT', 7, 2000, 2000, '这个卡名的效果1回合只能使用1次。 ①：把自己场上1只效果怪兽解放才能发动。这张卡从手卡特殊召唤。那之后，把持有和解放的怪兽的原本的种族·属性相同种族·属性的1只「后继者衍生物」（1星·攻/守0）在自己场上特殊召唤。'),
(52566270, 'Epsilon The Magnet Warrior', '磁石战士伊普西隆', '磁石の戦士ε', 'Effect Monster', 'Rock', 'EARTH', 4, 1300, 1500, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，从卡组把「磁石战士ε」以外的1只4星以下的「磁石战士」怪兽送去墓地才能发动。这张卡直到结束阶段当作和送去墓地的怪兽同名卡使用。那之后，可以从自己墓地选同名卡不在自己场上存在的1只「磁石战士」怪兽特殊召唤。'),
(98049934, 'Epurrely Beauty', '爱皮尔莉・美丽', 'エピュアリィ・ビューティ', 'XYZ Monster', 'Fairy', 'WATER', 2, 1600, 1100, '2星怪兽×2 ①：1回合1次，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。这张卡有「纯爱妖精可爱回忆」在作为超量素材的场合，这个效果在对方回合也能发动。 ②：自己把「纯爱妖精」速攻魔法卡发动时才能发动。场上的那张卡在这张卡下面重叠作为超量素材。那之后，可以选对方场上1只怪兽把表示形式变更。这个效果1回合可以使用最多3次。');